const r = await tools.exec_command({cmd:"python - <<'PY'
import cv2,numpy as np
im=cv2.imread('/app/target.png')
g=cv2.cvtColor(im,cv2.COLOR_BGR2GRAY)
b=(g<120).astype('uint8')*255
# skeleton via erosion + opening subtraction
sk=np.zeros_like(b); el=cv2.getStructuringElement(cv2.MORPH_CROSS,(3,3)); cur=b.copy()
while cv2.countNonZero(cur):
 er=cv2.erode(cur,el)
 op=cv2.dilate(er,el)
 sk=cv2.bitwise_or(sk,cv2.subtract(cur,op))
 cur=er
# restrict bounding, overlay blue
out=im.copy();out[sk>0]=[0,0,255]
cv2.imwrite('/tmp/skel.png',cv2.resize(out[220:800,250:760],None,fx=1.5,fy=1.5))
# skeleton endpoints/branch counts 8conn
ys,xs=np.where(sk>0); deg=cv2.filter2D((sk>0).astype(np.uint8),-1,np.ones((3,3),np.uint8))- (sk>0)
for name,xa,xb,ya,yb in [('left',250,490,220,620),('right',490,760,220,800)]:
 pts=[]
 for y,x in zip(*np.where((sk>0)&(np.indices(sk.shape)[1]>=xa)&(np.indices(sk.shape)[1]<xb)&(np.indices(sk.shape)[0]>=ya)&(np.indices(sk.shape)[0]<yb))):
  d=int(deg[y,x]);
  if d==1 or d>=3:pts.append((int(x),int(y),d))
 print(name,'points',len(pts),'specials',pts[:150])
